import sys; sys.path.insert(0,"/workspace/social/posts"); from build10 import build
B=r'''<style>.box p,.box li{font-size:20.5px;line-height:1.28}.box h2{font-size:26px;margin-bottom:5px}.tbl{font-size:18.5px}.note,.warn{font-size:17.5px}.tbl th,.tbl td{padding:3px 6px}.iq ol{font-size:19.5px;line-height:1.28}.pill{font-size:16.5px}.grid{gap:12px}.handle{bottom:-12px}.box{padding:10px 12px}.tagline{font-size:19.5px;margin-bottom:9px}</style>
<div class="title">🗂️ HxGN EAM Part Catalog Requests <span class="badge">CHEAT SHEET</span></div>
<div class="tagline">A request form for new or changed parts, pricing, suppliers, manufacturers and store data, approved before anything touches the Part master. (HxGN EAM Part Catalog Requests brief, 12.3)</div>
<div class="grid">
<div class="box c1"><h2>1. Why it exists</h2><ul><li>Clean part catalog = accurate <b>financial + inventory</b> reporting</li><li>Requestor fills the form, a <b>parts specialist</b> checks for duplicates</li><li>Nothing is inserted / updated until <b>approved</b></li></ul></div>
<div class="box c2"><h2>2. Two system types (CQTP)</h2><table class="tbl"><tr><th>Type</th><th>Requested Part field</th></tr><tr><td><b>New Part Request</b></td><td>Text field, follows <b>AUTOPNUM</b></td></tr><tr><td><b>Update Existing Part</b></td><td>Lookup to pick the part</td></tr></table></div>
<div class="box c3"><h2>3. Not supported (Update)</h2><ul><li>Track By Asset</li><li>Track By Kit</li><li>Repairable Spare</li><li>Calibration Standard</li><li>Track by Condition</li></ul></div>
<div class="box c4"><h2>4. Change Part Number</h2><ul><li>Update type: tick <b>Change Part Number</b> + enter <b>New Part Number</b></li><li>Pick an existing part = <b>merge duplicates</b></li><li>Or type a number that doesn't exist yet</li></ul><div class="note">Runs only on approval, like the Part right-click option.</div></div>
<div class="box c5"><h2>5. Preserve Part Data</h2><ul><li>Update only suppliers / manufacturers / store</li><li>Part record view stays untouched</li><li>Tip: cloned screen with it <b>checked + protected</b> = a "Min/Max Request"</li></ul></div>
<div class="box c6"><h2>6. Pricing rules</h2><ul><li>Updates only if Average / Last / Standard price entered</li><li>Price change creates a <b>CORR</b> transaction</li><li>Protect price fields to block updates</li></ul><table class="tbl"><tr><th>PRICELEV</th><th>Behaviour</th></tr><tr><td><b>P</b></td><td>Price Type required, defaults to <b>PRICETYP</b>; not for common-org parts</td></tr><tr><td><b>S</b></td><td>Pricing protected until <b>Include Store Request</b></td></tr></table></div>
<div class="box c7"><h2>7. Supplier / Manufacturer</h2><ul><li>Creates the record on approval if it doesn't exist</li><li>Existing record: fields default in, edits update it</li></ul><div class="warn">Old supplier catalog record is NOT kept as an alternate.</div></div>
<div class="box c8"><h2>8. Store + Approval</h2><ul><li><b>Include Store Request</b>: create / update the part's store record (reorder setup)</li><li>Approval Workflow entity: <b>Default Approver</b>, <b>Approval List</b></li><li>On approval: UDFs, comments, documents copy to the part</li><li>Approved = all fields protected, even status</li></ul></div>
<div class="bottom">
<div class="box" style="border-color:#1a5f7a"><h2 style="color:#1a5f7a">9a. Request flow</h2><div class="flow" style="flex-wrap:wrap;row-gap:4px"><span class="pill">Requestor fills form</span><span class="arr">→</span><span class="pill">Parts specialist review</span><span class="arr">→</span><span class="pill">Approval Workflow</span><span class="arr">→</span><span class="pill">Part / Supplier / Store updated</span></div></div>
<div class="box iq"><h2>9b. Consultant tips</h2><ol><li>Clone the screen per Type / Class (Screen Setup)</li><li>Use Change Part Number to merge duplicates</li><li>Protect price fields if finance owns pricing</li><li>Finance approval for keep-stock requests</li></ol></div>
<div class="box" style="border-color:#2d8a5a"><h2 style="color:#2d8a5a">9c. Key points</h2><ul><li>2 types: New / Update</li><li>Approve = write to EAM</li><li>Price change = CORR</li></ul></div>
</div></div>'''
build("/workspace/social/posts/2026-10-23-linkedin-eam-part-catalog-requests",B,1350,"Rahul Kumar")
